import{_ as s,o as a,c as n,a3 as o}from"./chunks/framework.SG7_9Yi6.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),t={name:"explanation/architecture.md"};function i(r,e,c,p,d,h){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Peregrin is the <em>policy</em> layer for coding-agent sessions and workflows: who may act on a session, when, and on which machine — plus the orchestration plane (campaigns, drivers, events, transport) on top. Session <em>mechanism</em> — attach, prompt, restore, per-agent stores — lives in <a href="https://9aia.com/sepia/" target="_blank" rel="noreferrer">sepia</a>, which peregrin consumes over a subprocess wire rather than by linking internals.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌─────────────── peregrin-hub ───────────────┐</span></span>
<span class="line"><span>                 │  hypha-hub gateway · sync · arbitration ·    │</span></span>
<span class="line"><span>                 │  fleet dispatch (headless — no UI on main)   │</span></span>
<span class="line"><span>                 └──────────────┬───────────────┬─────────────┘</span></span>
<span class="line"><span>                        HTTP+SSE │               │ HTTP+SSE</span></span>
<span class="line"><span>                  ┌──────────────▼──┐    ┌───────▼──────────┐</span></span>
<span class="line"><span>                  │ peregrin-node A │    │ peregrin-node B  │</span></span>
<span class="line"><span>                  │  session routes │    │  session routes  │</span></span>
<span class="line"><span>                  │  + entity plane │    │  + entity plane  │</span></span>
<span class="line"><span>                  └───────┬─────────┘    └────────┬─────────┘</span></span>
<span class="line"><span>                  spawn + │ ndjson JSON-RPC       │</span></span>
<span class="line"><span>                  ┌───────▼─────────┐    ┌────────▼─────────┐</span></span>
<span class="line"><span>                  │   sepia serve   │    │   sepia serve    │</span></span>
<span class="line"><span>                  │  session plane  │    │  session plane   │</span></span>
<span class="line"><span>                  └─────────────────┘    └──────────────────┘</span></span></code></pre></div><h2 id="mechanism-vs-policy" tabindex="-1">Mechanism vs policy <a class="header-anchor" href="#mechanism-vs-policy" aria-label="Permalink to &quot;Mechanism vs policy&quot;">​</a></h2><p>The split is deliberate: sepia does things <em>to</em> sessions; peregrin decides <em>who/when/where</em>. Concretely — <code>hypha-control</code> (the extracted substrate, a git dep of peregrin) holds the lock registry, takeover arbitration, and <code>pick_owner</code> routing; the hub consults it before forwarding; nodes report lock state up. Anything that mutates a session (prompt, attach, rewind) flows down to sepia with the policy decision already made.</p><h2 id="the-sepia-boundary" tabindex="-1">The sepia boundary <a class="header-anchor" href="#the-sepia-boundary" aria-label="Permalink to &quot;The sepia boundary&quot;">​</a></h2><p>A node never links <code>sepia-session</code> into orchestration code. It spawns <code>sepia serve</code> and drives it over ndjson JSON-RPC stdio — the same framing sepia&#39;s own store drivers speak — via <code>peregrin-session::ServicePlane</code>. An in-process <code>LocalPlane</code> remains selectable for dev (<code>PEREGRIN_SESSION_PLANE=local</code>/<code>inprocess</code>); both implement the same <code>SessionPlane</code> trait, so <code>peregrin-http</code> and everything above it is blind to which side of the fork it&#39;s on. The manifest handshake negotiates protocol versions at spawn.</p><h2 id="the-bupha-boundary" tabindex="-1">The bupha boundary <a class="header-anchor" href="#the-bupha-boundary" aria-label="Permalink to &quot;The bupha boundary&quot;">​</a></h2><p>CI is the same split seen from the other side. Peregrin owns all workflow semantics — including the gate itself: a repo&#39;s committed <code>workflows/gate.yaml</code> is a peregrin campaign composing <code>tamias:handl-gates//…</code> fragments, and forge webhook ingress is a campaign driver that normalizes deliveries into agnostic entities (<code>ci-job</code>). Bupha is the per-push runner adapter — queue, detached worktree@sha, runner, forge status write-back through <code>lasius-forge</code> — and in production never parses forge payloads; its own <code>github</code> source is the standalone/dev fallback. The contract between them is the <code>run.result</code> artifact (GH Checks-style status/conclusion/output): bupha maps <code>conclusion</code> onto the forge commit status. <code>ci.sh</code> is being retired in favor of <code>gate.yaml</code>.</p><h2 id="planes" tabindex="-1">Planes <a class="header-anchor" href="#planes" aria-label="Permalink to &quot;Planes&quot;">​</a></h2><ul><li><strong>Session plane</strong> — the sepia surface: sessions, agents, attach, prompts, events. Nodes own it; the hub proxies it.</li><li><strong>Entity plane (substrate)</strong> — the generic <code>hypha-*</code> layer: <code>Entity {id, kind, indexDoc}</code> + namespaced ops + opaque snapshots, the outbox, locks, sync, and the <code>/api/entities*</code> + generic routes (<code>/api/events</code>, <code>/api/node</code>, <code>/api/pair</code>, <code>/api/auth/*</code>, <code>/api/push/*</code>, <code>/api/fs</code>, <code>/api/user</code>, <code>/api/health</code>). Hypha never names an integration&#39;s type; peregrin registers its kinds.</li><li><strong>Integration planes</strong> — peregrin&#39;s own: sessions register as <code>kind=&quot;sepia-session&quot;</code> entities (via the <code>sepia-peregrin</code> adapter in the sepia repo), campaigns as <code>kind=&quot;campaign&quot;</code> entities (<code>campaign.start|pause|resume|cancel|signal</code> ops, <code>campaign serve</code> hosting, <code>runs_on</code> fleet scheduling). Campaign <em>workflows</em> run on <code>peregrin-engine</code> + loaders + templates — the event bus, remote transport, and the outbox for offline ordering.</li><li><strong>App plane</strong> — <code>peregrin-http</code> composes the session routes with hypha&#39;s generic routes under one listener; <code>peregrin-hub</code> is a thin <code>hypha-hub</code> gateway (merged entity views, sync, arbitration, fleet dispatch). Node-local overlay state (<code>PEREGRIN_META</code> — pins, archives, run spans) is node-owned, not part of the session wire. The Leptos web UI is experimental and lives on the <code>experimental/web</code> branch — <code>main</code> is headless.</li></ul><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p>Policy crates are pure; every I/O seam is a port (<code>peregrin-{store,bus,remote,config,loader,driver,queue}</code>) with impls behind it (<code>-json</code>, the in-process <code>LocalBus</code>, <code>-http</code>, <code>-toml</code>, <code>-yaml</code>, <code>-sqlite</code>, plus the <code>peregrin-driver-*</code> family). Secrets resolve through cuora&#39;s <code>cuora-secret*</code> family and service lifecycle rides <code>tamias-deploy-systemd</code> — both git deps; there is no <code>peregrin-secret-*</code> shim anymore. Engine semantics are documented in <code>project/adrs/</code> — read those before changing campaign behaviour.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>In the org&#39;s layering — <strong>delivery</strong> (tamias distribution, scarab config/templates, tarsi releases, bupha CI, hypha entity sync) → <strong>memory</strong> (myco records, kuda code maps) → <strong>process</strong> (sturn coordination, cuora secrets, mimus proofs, cicada schedules, lasius workspace, sepia sessions, <strong>peregrin</strong>: campaigns, drivers, fleet dispatch over those layers) → <strong>interface</strong> (<strong>pavo</strong>: views, MCP fronts, the experimental web UI).</p><p>Peregrin sits in the process layer: it orchestrates campaigns <em>on</em> hypha&#39;s entity substrate — campaigns register as <code>kind=&quot;campaign&quot;</code> entities and fleet state lives on the same plane as everything else — while consuming the lower layers as providers: <code>sepia serve</code> for sessions, sturn&#39;s WAL via the <code>sturn</code> driver, tarsi&#39;s ops inside the <code>libraries/release</code> campaign. It exposes one surface upward: the hub&#39;s merged API plus the tamias pack that ships the <code>peregrin</code> command.</p>`,16)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
